sessions = {}  # session id -> user id, in this server's memory

def login(request):
    user = check_password(request.form)
    sid = new_session_id()
    sessions[sid] = user.id
    return set_cookie("sid", sid)

def my_links(request):
    user_id = sessions.get(request.cookies["sid"])
    if user_id is None:
        return redirect("/login")
    return db.links_owned_by(user_id)

DB = {"a": "https://example.com/1", "b": "https://example.com/2"}
cache = {}
db_reads = 0

def get_url(code):
    global db_reads
    if code in cache:
        return cache[code]
    db_reads += 1
    url = DB[code]
    cache[code] = url
    return url

for code in ["a", "b", "a", "a", "b", "a"]:
    get_url(code)
print(db_reads)
print(f"hit ratio: {(6 - db_reads) / 6:.0%}")

def get_url(code):
    url = cache.get(code)
    if url is None:
        url = db.query_one("SELECT long_url FROM links WHERE code = %s", code)
        cache.set(code, url)  # no TTL: kept until evicted
    return url

def update_url(code, new_url):
    db.execute("UPDATE links SET long_url = %s WHERE code = %s", new_url, code)
    return "ok"

def create_link(user, long_url):
    code = new_code()
    leader.execute("INSERT INTO links (code, long_url, owner) VALUES (%s, %s, %s)",
                   code, long_url, user.id)
    return redirect(f"/links/{code}")

def show_link(code):
    row = replica.query_one("SELECT * FROM links WHERE code = %s", code)
    if row is None:
        return not_found()
    return render(row)

def handle_click(msg):
    # msg looks like {"id": "m-981", "code": "x7Kp2"}
